					methodDecl.restype = maker.AnnotatedType(com.sun.tools.javac.util.List.of(marker), resType);
				} else if (JavacHandlerUtil.JCAnnotatedTypeReflect.is(resType)) {
					com.sun.tools.javac.util.List<JCAnnotation> annotations = JavacHandlerUtil.JCAnnotatedTypeReflect.getAnnotations(resType);
					JavacHandlerUtil.JCAnnotatedTypeReflect.setAnnotations(resType, annotations.prepend(marker));
				} else if (resType instanceof JCPrimitiveTypeTree || resType instanceof JCIdent) {
					methodDecl.mods = maker.Modifiers(methodMods.flags, methodMods.annotations == null ? com.sun.tools.javac.util.List.of(marker) : methodMods.annotations.prepend(marker));
